 panel.querySelector('.order-sheet-drawings').innerHTML='<h3>Tài liệu thiết kế đính kèm</h3>'+productionDocumentGroups(files,'sheet',d)+(s.links||[]).map(l=>'<p><a href="'+e(l.url)+'" target="_blank" rel="noopener noreferrer">'+e(l.name||l.title||l.url)+'</a></p>').join('');
