 rows.push([pe(rows.length+1),'QC',pe(j.progress.qc.actor||'Chưa ghi nhận'),'',pe(j.progress.qc.passed||0)+' đạt / '+pe(j.progress.qc.rejected||0)+' không đạt',pe(j.progress.deadline||''),j.progress.qc.at?'Đã ghi nhận QC':'Chờ QC',pe(j.progress.qc.note||''),'<button data-production-tab="qc">Mở QC</button>']);
 rows.push([pe(rows.length+1),'Hoàn thành',pe(j.progress.assigneeName||'Chưa phân công'),'','',pe(j.progress.deadline||''),j.state==='completed'?'Đã hoàn thành':'Chờ xác nhận riêng','','<button data-production-tab="qc">Xác nhận hoàn thành</button>']);
 el.insertAdjacentHTML('afterbegin',productionStageBoard(j)+'<section class="production-process-overview"><h3>Quy trình sản xuất của lệnh</h3><p>Theo thứ tự công nghệ đã duyệt. Khối lượng ghi nhận từ bước sau không thay thế duyệt hoàn thành, đối soát kho hoặc QC.</p>'+(!j.packet.flowApproved?'<p class="notice">Chưa duyệt tiến trình công nghệ. <button type="button" data-flow-open>Lập / rà soát quy trình</button></p>':'<p>Đã duyệt bởi '+pe(j.packet.flowApproved.admin)+' · '+pe(TPDisplay.date(j.packet.flowApproved.at,true))+'</p>')+opsTable(['Bước','Công đoạn / đối tượng','Chịu trách nhiệm','Máy','Sản lượng','Tiến độ','Trạng thái','Vướng mắc','Thao tác'],rows)+'<details><summary>Tham khảo chuỗi công đoạn</summary><p>Cắt → Tiện → Phay → Hàn → Sơn → Lắp ráp → QC → Hoàn thành. Khai các công đoạn thực tế của sản phẩm, sắp thứ tự và gửi duyệt tại phần công nghệ; QC và hoàn thành là hai bước kiểm soát riêng.</p></details></section>');
