function productionStageBoard(j){
 const groups=new Map();for(const o of j.packet.operations){if(!groups.has(o.name))groups.set(o.name,[]);groups.get(o.name).push(o);}
 return '<section class="production-stage-board" aria-label="Quy trình sản xuất theo công đoạn">'+[...groups].map(([name,ops])=>'<section class="production-stage-column"><h4>'+pe(name)+' <span>'+ops.length+'</span></h4>'+ops.map(o=>{const p=j.progress.operations.find(x=>x.id===o.id)||{},pct=o.quantity>0?Math.min(100,Math.round((p.output||0)/o.quantity*100)):0;return '<button type="button" class="production-stage-card" data-process-operation="'+pe(o.id)+'"><strong>'+pe(o.object)+'</strong><small>'+pe(Production.people.find(x=>x.id===p.assignee)?.name||'Chưa phân công')+'</small><small>'+pe(p.output||0)+' / '+pe(o.quantity)+' '+pe(o.outputUnit)+'</small><progress max="100" value="'+pct+'"></progress><span>'+pct+'% · '+pe(productionStatus[p.status]||'Chưa bắt đầu')+'</span>'+(p.issue?'<small class="warning">'+pe(p.issue)+'</small>':'')+'</button>';}).join('')+'</section>').join('')+'<section class="production-stage-column"><h4>QC</h4><button class="production-stage-card" data-production-tab="qc">'+pe(j.progress.qc.passed||0)+' / '+pe(j.quantity)+' đạt<br>'+pe(j.progress.qc.rejected||0)+' lỗi</button></section><section class="production-stage-column"><h4>Hoàn thành</h4><button class="production-stage-card" data-production-tab="qc">'+(j.state==='completed'?'Đã duyệt hoàn thành':'Chờ duyệt hoàn thành')+'</button></section></section>';
}
